from ortools.linear_solver import pywraplp
import json

def solve_vertex_cover():
    N = 34

    E = set()

    for j in range(1, 34):
        E.add((0, j))

    for j in [2, 3, 4, 8, 13, 17, 18, 20, 22, 31]:
        E.add((1, j))

    for j in [3, 8, 9, 13, 27, 28, 32, 33]:
        E.add((2, j))

    for j in [7, 12, 13]:
        E.add((3, j))

    for j in [6, 10]:
        E.add((4, j))

    for j in [6, 10, 16]:
        E.add((5, j))

    for j in [16]:
        E.add((6, j))

    for j in [8]:
        E.add((7, j))

    for j in [32, 33]:
        E.add((8, j))

    for j in [33]:
        E.add((9, j))

    for j in [33]:
        E.add((13, j))

    for j in [32, 33]:
        E.add((14, j))

    for j in [32, 33]:
        E.add((15, j))

    for j in [32, 33]:
        E.add((18, j))

    for j in [32, 33]:
        E.add((19, j))

    for j in [32, 33]:
        E.add((20, j))

    for j in [32, 33]:
        E.add((21, j))

    for j in [32, 33]:
        E.add((22, j))

    for j in [25, 27, 29, 32, 33]:
        E.add((23, j))

    for j in [25, 27, 31]:
        E.add((24, j))

    for j in [31]:
        E.add((25, j))

    for j in [29, 33]:
        E.add((26, j))

    for j in [33]:
        E.add((27, j))

    for j in [31, 33]:
        E.add((28, j))

    for j in [32, 33]:
        E.add((29, j))

    for j in [32, 33]:
        E.add((30, j))

    for j in [32, 33]:
        E.add((31, j))

    for j in [33]:
        E.add((32, j))

    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        print(json.dumps({
            "selected_vertices": [],
            "num_vertices_selected": 0
        }))
        return

    x = [solver.BoolVar(f"x[{i}]") for i in range(N)]

    for i, j in E:
        solver.Add(x[i] + x[j] >= 1)

    solver.Minimize(sum(x[i] for i in range(N)))

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        selected_vertices = [i for i in range(N) if x[i].solution_value() > 0.5]
        num_vertices_selected = len(selected_vertices)
        print(json.dumps({
            "selected_vertices": selected_vertices,
            "num_vertices_selected": num_vertices_selected
        }))
    else:
        print(json.dumps({
            "selected_vertices": [],
            "num_vertices_selected": 0
        }))

if __name__ == "__main__":
    solve_vertex_cover()
